<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Demo Registro de Estudiantes</title><link rel="stylesheet" href="demo-style.css?v=5"><style>table{width:100%;border-collapse:collapse}th,td{padding:14px;border-bottom:1px solid var(--line);text-align:left}th{color:var(--primary)}</style></head><body><nav class="demo-nav"><div class="demo-nav-inner"><a class="brand" href="../index.php#proyectos">← Volver al portafolio</a><a class="btn primary" href="#">Demo local</a></div></nav><main class="wrap"><section class="hero"><div><span class="kicker">Sistema académico</span><h1>Registro de Estudiantes</h1><p>Demo de una tabla administrativa simple para visualizar estudiantes, carrera y estado.</p></div><div class="panel"><label>Nombre estudiante</label><input id="name" placeholder="Ej: Leonardo Aguilera"><button class="btn primary" onclick="addStudent()" style="margin-top:12px">Registrar</button></div></section><section class="panel"><h2>Estudiantes registrados</h2><table><thead><tr><th>Nombre</th><th>Carrera</th><th>Estado</th></tr></thead><tbody id="rows"></tbody></table></section></main><script>let data=['Camila Soto','Matías Rivas','Leonardo Aguilera'];function render(){rows.innerHTML=data.map(n=>`<tr><td>${n}</td><td>Técnico en Informática</td><td><span class="pill">Activo</span></td></tr>`).join('')}function addStudent(){let v=name.value.trim();if(!v)return;data.unshift(v);name.value='';render()}render();</script></body></html>
